mapper.select:
SELECT 
FROM leave_application l

WHERE l.tenant_id = #{tenantId}
  AND l.id = #{id}

SELECT 
FROM leave_application l

WHERE l.tenant_id = #{tenantId}


    AND (
        COALESCE(NULLIF(applicant.display_name, ''), applicant.username) ILIKE CONCAT('%', #{keyword}, '%') ESCAPE '\'
        OR COALESCE(l.reason, '') ILIKE CONCAT('%', #{keyword}, '%') ESCAPE '\'
    )


    AND l.leave_type = #{leaveType}

ORDER BY l.submitted_at DESC NULLS LAST, l.created_at DESC, l.id DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM leave_application
WHERE tenant_id = #{tenantId}

    AND status = #{status}


    AND submitted_at >= #{from}


    AND submitted_at <= #{to}


    AND (
        COALESCE(NULLIF((
            SELECT display_name FROM app_user u WHERE u.id = leave_application.applicant_user_id
        ), ''), (
            SELECT username FROM app_user u WHERE u.id = leave_application.applicant_user_id
        )) ILIKE CONCAT('%', #{keyword}, '%') ESCAPE '\'
        OR COALESCE(reason, '') ILIKE CONCAT('%', #{keyword}, '%') ESCAPE '\'
    )


    AND leave_type = #{leaveType}

SELECT 
FROM leave_application l

WHERE l.tenant_id = #{tenantId}
  AND l.applicant_user_id = #{userId}

    AND l.status = #{status}

ORDER BY l.created_at DESC, l.id DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM leave_application
WHERE tenant_id = #{tenantId}
  AND applicant_user_id = #{userId}

    AND status = #{status}

SELECT id, name, department_name AS departmentName, position_name AS positionName, CASE WHEN id = #{recommendedId} THEN TRUE ELSE FALSE END AS recommended, avatar, updatedAt, NULL AS avatarUrl FROM eligible
WHERE name ILIKE CONCAT('%', #{keyword}, '%') OR COALESCE(department_name, '') ILIKE CONCAT('%', #{keyword}, '%') OR COALESCE(position_name, '') ILIKE CONCAT('%', #{keyword}, '%')
ORDER BY CASE WHEN id = #{recommendedId} THEN 0 ELSE 1 END, depth, name, id LIMIT #{size} OFFSET #{offset}
